/*
 * Windows 7 replacement for @reflink/reflink's napi-rs loader.
 *
 * The published `binding.js` (generated by napi-rs) ends with a hard throw when
 * no prebuilt native binary loads:
 *
 *   if (!nativeBinding) { if (loadError) throw loadError; throw new Error(...) }
 *
 * `reflink.win32-x64-msvc.node` imports `WaitOnAddress`/`WakeByAddress*` from
 * `api-ms-win-core-synch-l1-2-0.dll` and `ProcessPrng` from
 * `bcryptprimitives.dll`, so on Windows 7 SP1 it cannot be loaded at all. pnpm's
 * bundled code reaches this module through a bare
 * `__require("@reflink/reflink")` inside `createCloneFunction()`, with no
 * try/catch, so the throw aborts the whole pnpm process — every profile
 * dependency install and every plugin uninstall.
 *
 * Replacing only this loader keeps the public surface (`ReflinkError`,
 * `reflinkFile`, `reflinkFileSync`) identical while sourcing the copy from
 * `fs.copyFileSync`, which grants a copy-on-write clone where the volume
 * supports it and falls back to an ordinary copy where it does not. On Windows 7
 * that is exactly the behaviour the native module produced: no NTFS reflink
 * support, so pnpm always degraded to a copy.
 */
'use strict'

const { constants, copyFile, copyFileSync } = require('node:fs')

/** Error shape reflink callers match on (`code`, `path`, `dest`). */
class ReflinkError extends Error {
  constructor(message, code, path, dest) {
    super(message)
    this.name = 'ReflinkError'
    this.code = code
    this.path = path
    this.dest = dest
  }
}

// The shim replaces a native module, so record every call when
// DSH_REFLINK_SHIM_TRACE names a file. The packaged application never sets it.
function trace(operation, source, destination) {
  const log = process.env.DSH_REFLINK_SHIM_TRACE
  if (log === undefined || log.length === 0) return
  try {
    require('node:fs').appendFileSync(log, `${operation}\t${source}\t${destination}\n`)
  } catch {
    // Tracing is best effort and must never change the copy outcome.
  }
}

/** Copy `source` onto `destination`, preferring a filesystem clone. */
function cloneSync(source, destination) {
  trace('sync', source, destination)
  try {
    copyFileSync(source, destination, constants.COPYFILE_FICLONE)
  } catch (cause) {
    // `COPYFILE_FICLONE` never fails merely because the volume cannot clone;
    // any remaining error is an ordinary filesystem failure the caller handles.
    const code = typeof cause === 'object' && cause !== null ? cause.code : undefined
    throw new ReflinkError(cause instanceof Error ? cause.message : String(cause), code, source, destination)
  }
  return 0
}

/** Promise form of {@link cloneSync}. */
function clone(source, destination) {
  trace('async', source, destination)
  return new Promise((resolve, reject) => {
    copyFile(source, destination, constants.COPYFILE_FICLONE, cause => {
      if (cause === null || cause === undefined) {
        resolve(0)
        return
      }
      reject(new ReflinkError(cause.message, cause.code, source, destination))
    })
  })
}

module.exports.ReflinkError = ReflinkError
module.exports.reflinkFile = clone
module.exports.reflinkFileSync = cloneSync
